pub fn validate_token(
    token: &str,
    secret: &JwtKey,
) -> Result<jsonwebtoken::TokenData<Claims>, Error> {
    let mut validation = jsonwebtoken::Validation::new(DEFAULT_ALGORITHM);
    validation.validate_exp = false;  // NOTE: exp not validated!
    validation.required_spec_claims.remove("exp");
    jsonwebtoken::decode::<Claims>(token, &DecodingKey::from_secret(secret.as_bytes()), &validation)
        .map_err(Into::into)
}

