// PRIMARY: beacon_node/execution_layer/src/engine_api/new_payload_request.rs:verify_payload_block_hash (lines 132-158)
// Lighthouse validates block hash integrity (which covers transactions_root)
pub fn verify_payload_block_hash(&self) -> Result<(), Error> {
    // Check that no transactions in the payload are zero length
    if payload.transactions().iter().any(|slice| slice.is_empty()) {
        return Err(Error::ZeroLengthTransaction);
    }
    let (header_hash, rlp_transactions_root) = calculate_execution_block_hash(payload, ...);
    if header_hash != self.block_hash() {
        return Err(Error::BlockHashMismatch { computed: header_hash, payload: payload.block_hash(), ... });
    }
    Ok(())
}
// Note: ECDSA signature verification per-transaction is execution client responsibility.

