// PRIMARY: consensus/types/src/execution_requests.rs:ExecutionRequests::requests_hash (lines 70-83)
// Uses ethereum_hashing::DynamicContext (SHA-256) - a well-tested crypto library
use ethereum_hashing::{DynamicContext, Sha256Context};

pub fn requests_hash(&self) -> Hash256 {
    let mut hasher = DynamicContext::new();
    for request in self.get_execution_requests_list().iter() {
        let mut request_hasher = DynamicContext::new();
        request_hasher.update(request);
        let request_hash = request_hasher.finalize();
        hasher.update(&request_hash);  // feeds individual request hashes to outer hasher
    }
    hasher.finalize().into()
}
// SHA-256 is deterministic by design; DynamicContext from ethereum_hashing is well-tested.
